\label{lemma0}
	Suppose that $\varphi(\cdot)$ is continuously differentiable with an $L$-Lipschitz gradient on a convex region containing $Z,Y,W$, and let $h(\cdot)$ be proper, closed, and convex. If $Y=P_{\eta\mu}(Z-\eta D)$ for $\eta>0$ and $W\in\text{dom}~h(\cdot)$, then
	\begin{equation*}\label{ preinexactproximal}
		\begin{aligned}
			\varphi(Y)+h(Y) &\leq \varphi(W)+h(W) 	+\langle\nabla\varphi(Z)-D,Y-W\rangle\\
			&-\frac{1}{\eta}\langle Y-Z,Y-W\rangle +\frac{L}{2}\|Y-Z\|_F^2 +\frac{L}{2}\|W-Z\|_F^2.
		\end{aligned}
	\end{equation*}

Following the proximal optimality condition and the subgradient inequality, it derives \begin{equation*}
		\begin{aligned}
        h(Y)-h(W)\leq-\langle D,Y-W\rangle-\frac{1}{\eta}\langle Y-Z,Y-W\rangle.	
        \end{aligned}
	\end{equation*}	The Lipschitz continuity of $\nabla\varphi$ implies
	\begin{equation*}
		\begin{aligned}
        \varphi(Y)-\varphi(W)	\leq\langle\nabla\varphi(Z),Y-W\rangle+\frac{L}{2}\|Y-Z\|_F^2 +\frac{L}{2}\|W-Z\|_F^2.	
        \end{aligned}
	\end{equation*}
	Adding the two inequalities proves the result.

\label{assumption1}
	    There exist constants $L_{1,p}>0$, $p=1,\ldots,m$, such that, for any feasible $U_p$ and any $V_1,V_2$ generated by the algorithm, \begin{equation*}
		\begin{aligned} 
        \|\nabla_{U_p}f_p(U_p,V_1)-\nabla_{U_p}f_p(U_p,V_2)\|_F\leq L_{1,p}\|V_1-V_2\|_F.
        \end{aligned}
	\end{equation*}

\label{LeA.12}
		If the parameter $\tilde\eta$ satisfies $0<\tilde\eta\leq\frac{\eta_g}{\sqrt{20}L_2},$ then, for every $s\geq1$, it holds that
		\begin{equation*}\label{local_drift_bound}
			\begin{aligned}
				\sum_{k=0}^{\tau-1}\sum_{p=1}^{m}\|V_p^{s,k}-V^s\|_F^2	&\le 6\tau\|\Lambda^s-\overline{\Lambda}^s\|_F^2+24m\tau^3\alpha^2c_h^2\\
				&+6m\tau^3\alpha^2\|\widetilde{\nabla}h(\widetilde V^{s+1})
				+\nabla_V f(\{U_p^{s,0}\},V^s)\|_F^2\\
				&+12\alpha^2\tau^4\sum_{p=1}^{m}\sum_{k=0}^{\tau-1}L_{3,p}^2\|\Delta U_p^{s,k}\|_F^2,
			\end{aligned}
		\end{equation*}
		where $\Lambda_{a}^s=\frac1m\sum_{p=1}^{m}\Lambda_p^s,~\Lambda^s=\text{col}~\{\Lambda_1^s,\cdots,\Lambda_m^s\},~\overline{\Lambda}^s=\text{col}~\{\Lambda_{a}^s,\cdots,
		\Lambda_{a}^s\},~\widetilde{\nabla}h(\widetilde V^{s+1})\in\partial h(\widetilde V^{s+1}),~ \Delta U_p^{s,k} =U_p^{s,k+1}-U_p^{s,k},$ and
       $ \Lambda_p^s =\alpha\tau ( \nabla_V f_p(U_p^{s,0},V^s) +\frac{1}{m}\sum_{p=1}^{m}G_p^{s-1} -G_p^{s-1} ).$

\label{LeA.21}
		For every $s=1,\cdots,T$, it holds that
		\begin{equation*}\label{Lambda_recursion_compact}
			\begin{aligned}
				&\frac{1}{m}\|\Lambda^{s+1}-\overline{\Lambda}^{s+1}\|_F^2-	2\alpha^2\tau^2L_2^2	\|V^{s+1}-V^s\|_F^2\\
				&\leq\frac{4\alpha^2\tau L_2^2}{m}\sum_{p=1}^{m}\sum_{k=0}^{\tau-1}\|V_p^{s,k}-V^s\|_F^2+\frac{2\alpha^2\tau^2(\tau-1)}{m}\sum_{p=1}^{m}\sum_{k=0}^{\tau-1}L_{3,p}^2\|\Delta U_p^{s,k}\|_F^2.
			\end{aligned}
		\end{equation*}

\label{LeA.3}
		Under the update rule $ U_p^{s+1,0}=U_p^{s,\tau},$ for communication round $s$, it holds that
		\begin{equation}\label{roundwise_U_descent_extended}
			\begin{aligned}
				&F(\{U_p^{s+1,0}\},V^{s+1})-F(\{U_p^{s,0}\},V^{s+1})\\
				&\leq -\frac{\rho_1}{4mL_{3,a}^2} \sum_{p=1}^{m}\sum_{k=0}^{\tau-1}L_{3,p}^2\|\Delta U_p^{s,k}\|_F^2 + \frac{1}{m\rho_1} \sum_{p=1}^{m}\sum_{k=0}^{\tau-1} L_{1,p}^2 \|V_p^{s,k}-V^{s+1}\|_F^2,
			\end{aligned}
		\end{equation}
		where $	L_{3,a}=\max_{p}L_{3,p}.$

\label{LeA.4}
		Suppose that Assumption \ref{assumption1}-\ref{assumption3} hold. Then, for communication round $s$, local iteration $k$, and client $p$, it has
		\begin{equation*}
			\begin{aligned}
				r_p^{s,k+1} \leq 
				2L_{1,p}^{2} \|V_p^{s,k}-V^s\|_F^2 + 2\rho_1^2 \|\Delta U_p^{s,k}\|_F^2,
			\end{aligned}
		\end{equation*}
		where
		\begin{equation*}
        \begin{aligned}
			r_p^{s,k+1} &= \text{dist}^{2}~( 0,  \nabla_{U_p}f_p(U_p^{s,k+1},V^s) + N_{\mathcal O_p}(U_p^{s,k+1}) ),\\
            \mathcal O_p &= \{ U\in\mathbb R^{d_p\times r}: U\geq 0,\ U^\top U=I \}
		\end{aligned}
        \end{equation*} is the feasible set for the local matrix, and $N_{\mathcal O_p}(U)$ denotes the limiting normal cone to $\mathcal O_p$ at the matrix $U$.

\label{Theorem}
	Under Assumptions~\ref{assumption1}-\ref{assumption3}, let $L_{1,a}=\max_{p}L_{1,p}$. If the step sizes and the proximal parameter satisfy
		\begin{equation}\label{final_parameter_conditions}
			\begin{aligned}
				& 0<\tilde{\eta}\leq\frac{1}{10L_2},~\eta_g\geq\frac{3}{2},\\
				&\rho_1> \max\{ 72\tau\tilde{\eta}L_{1,a}^2, 8L_{3,a}^2( \tilde{\eta} ( \frac{\tau+1}{2} + 12L_2^2\alpha^2\tau^3 ) \\
				&+ \frac{ 2\alpha^2\tau^2(\tau-1) + 48\alpha^4\tau^5L_2^2 }{\tilde{\eta}}), 8\sqrt{3} L_{3,a}L_{1,a}\alpha\tau^2 \}.
			\end{aligned}
		\end{equation}
		Then, there exist constants $c_1,c_2,c_3>0$ such that, for every $T\geq1$,
		\begin{equation*}\label{eq:joint-descent-bound}
			\frac{1}{T}\sum_{s=1}^{T} (c_1R_V^s +c_2C_s +c_3 A_s ) \leq \frac{\Phi^1}{T}
			+c_4 c_h^2.
		\end{equation*}
		Consequently,
		\begin{equation*}\label{eq:V-residual-bound}
			\frac{1}{T}\sum_{s=1}^{T}R_V^s \leq \frac{\Phi^1}{c_1T}+ \frac{c_4}{c_1}c_h^2,
		\end{equation*}
		where $c_1=(\tilde{\eta} (\frac12-L_2\tilde{\eta} -6L_2^2\tau^2\alpha^2 ) - \frac{24\alpha^4\tau^4L_2^2}{\tilde{\eta}} - \frac{12\tau^3\alpha^2L_{1,a}^2}{\rho_1}),~ c_4 = 24\tilde{\eta}L_2^2\tau^2\alpha^2 + \frac{96\alpha^4\tau^4L_2^2}{\tilde{\eta}} + \frac{48\tau^3\alpha^2L_{1,a}^2}{\rho_1},$ and under \eqref{final_parameter_conditions}, it holds that $c_1>0$.

The proof proceeds in four steps.

    \textbf{Step 1: It reformulates the global update for $V^{s+1}$.}

		Algorithm~\ref{al1} gives $V^s=\mathcal P_{\tilde\eta\mu}(\overline V^s)$. The definition of $f(\{U_p\},V)$ yields
		\begin{equation*}
			\nabla_V f(\{  U^{s,0}\},V^s)
			=	\frac{1}{m}\sum_{p=1}^{m}	\nabla_V f_p(U_p^{s,0},V^s).
		\end{equation*}
		and introduce the averaged local gradient direction
        \begin{equation*}\label{aggregated_direction}
G^s=\frac{1}{m}\sum_{p=1}^{m}G_p^s.
\end{equation*}





		Summing the local updates in Algorithm~\ref{al1} and using
$\widehat V_p^{s,0}=V^s$ yields
		\begin{equation}\label{cumulpreproxupdate}
			\begin{aligned}
				\widehat V_p^{s,\tau}=V^s-\alpha\sum_{k=0}^{\tau-1}	(\nabla_V f_p	(U_p^{s,k+1},V_p^{s,k})	+C_p^s).
			\end{aligned}
		\end{equation}
		Substituting \eqref{cumulpreproxupdate} into the global update gives
		\begin{equation*}
			\begin{aligned}
				\overline {V}^{s+1}&=	V^s-\frac{\eta_g\alpha}{m}\sum_{p=1}^{m}\sum_{k=0}^{\tau-1}
				(\nabla_V f_p(U_p^{s,k+1},V_p^{s,k})+C_p^s)	\\
				&=	V^s	-\eta_g\alpha\tau
				(\frac{1}{m\tau}\sum_{p=1}^{m}\sum_{k=0}^{\tau-1}\nabla_V f_p(	U_p^{s,k+1},V_p^{s,k})+\frac{1}{m}\sum_{p=1}^{m}C_p^s).
			\end{aligned}
		\end{equation*}
		Since the client drift correction terms satisfy $\frac{1}{m}\sum_{p=1}^{m}C_p^s	=0,$
		and $\tilde{\eta}=\eta_g\alpha\tau$, the global pre-proximal variable can be equivalently written as $\overline {V}^{s+1}= V^s-\tilde{\eta}G^s.$ Consequently, by applying the global proximal operator, the global post-proximal iterate satisfies
		\begin{equation*}\label{global_proximal_gradient_form}
			V^{s+1}	=\mathcal P_{\tilde{\eta}\mu}(	V^s-\tilde{\eta}G^s).
		\end{equation*}

	\textbf{Step 2: It bounds the change in $F(\{U_p^{s,0}\},V^s)$ over one communication round.}

		Applying Lemma~\ref{lemma0} to the virtual iterate the virtual iterate $\widetilde{V}^{s+1}$, using $Y=\widetilde{V}^{s+1},Z=W=V^s,$ and $D=\nabla_V f(\{ U^{s,0}\},V^s)$ yields
		\begin{equation*}
			\begin{aligned}
				F(\{ U^{s,0}\},\widetilde V^{s+1}) &\leq F(\{ U^{s,0}\},{V}^{s}) +(\frac{L_2}{2}- \frac{1}{\tilde{\eta}})\| \widetilde{V}^{s+1} - {V}^{s} \|_{F}^2.
			\end{aligned}
		\end{equation*}
		For the actual iterate $V^{s+1}$, using $Y={V}^{s+1},X={V}^{s} ,W=\widetilde{V}^{s+1}$ and $D=G^{s}$ in Lemma~\ref{lemma0} yields
		\begin{equation*}
			\begin{aligned}
				&\quad F(\{ U^{s,0}\},V^{s+1})\\
                &\leq F(\{ U^{s,0}\},\widetilde{V}^{s+1}) - \frac{1}{\tilde{\eta}} \langle	V^{s+1}-V^s, V^{s+1}-\widetilde V^{s+1} \rangle + \frac{L_2}{2} \| {V}^{s+1} - {V}^{s} \|_{F}^2\\
				&+ \langle \nabla_V f(\{ U^{s,0}\},{V}^{s}) - G^{s}, {V}^{s+1} - \widetilde{V}^{s+1} \rangle   + \frac{L_2}{2} \| \widetilde{V}^{s+1} -  {V}^{s}\|_{F}^2\\
				&\leq F(\{U^{s,0}\},\widetilde V^{s+1}) + \langle \nabla_V f(\{U^{s,0}\},V^s)-G^s,
				V^{s+1}-\widetilde V^{s+1} \rangle \\
				& + (\frac{L_2}{2} - \frac{1}{2\tilde{\eta}}) \|V^{s+1}-V^s\|_F^2 + ( \frac{L_2}{2} + \frac{1}{2\tilde{\eta}} ) \|\widetilde V^{s+1}-V^s\|_F^2 - \frac{1}{2\tilde{\eta}} \|V^{s+1}-\widetilde V^{s+1}\|_F^2.
			\end{aligned}
		\end{equation*}

		To eliminate the virtual function value $F(\{ U^{s,0}\},\widetilde{V}^{s+1})$, the above inequalities can be added to obtain
		\begin{equation}\label{66}
			\begin{aligned}
				&\quad F(\{ U^{s,0}\},V^{s+1})\\
				&\leq F(\{ U^{s,0}\},{V}^{s})+ (\frac{L_2}{2}- \frac{1}{2\tilde{\eta}})\| V^{s+1}-V^s \|_{F}^2  \\
                &+ \underbrace{\langle \nabla_V f(\{ U^{s,0}\},V^s)-G^s,
					V^{s+1}-\widetilde V^{s+1} \rangle}_{(\text{I})}\\
				&+ (L_2-\frac{1}{2\tilde{\eta}}) \| \widetilde{V}^{s+1} - V^s \|_{F}^2- \underbrace{\frac{1}{2\tilde{\eta}}\| {V}^{s+1} - \widetilde{V}^{s+1} \|_{F}^2}_{(\text{II})}.
			\end{aligned}
		\end{equation}

		By Young's inequality, $(\text{I})-(\text{II}) \leq\|\nabla_V f( \{U^{s,0}\},V^s)-G^s\|_{F}^{2}.$
		Using the definitions of $\nabla_V f(\{U_p^{s,0}\} ,V^s)$ and $G^s$, it has
		\begin{equation*}
			\begin{aligned}
				\nabla_V f( \{U^{s,0}\},V^s)-G^s  = \frac{1}{m\tau} \sum_{p=1}^{m}
				\sum_{k=0}^{\tau-1}( \nabla_V f_p(U_p^{s,0},V^s) - \nabla_V f_p(U_p^{s,k+1},V_p^{s,k})).
			\end{aligned}
		\end{equation*}
		Hence, by Jensen's inequality,
		\begin{equation*}
			\begin{aligned}
				\|\nabla_V f( \{U^{s,0}\},V^s)-G^s\|_F^2 \leq \frac{1}{m\tau} \sum_{p=1}^{m} \sum_{k=0}^{\tau-1} \| \nabla_V f_p(U_p^{s,0},V^s) - \nabla_V f_p(U_p^{s,k+1},V_p^{s,k}) \|_F^2 .
			\end{aligned}
		\end{equation*}
		Moreover, by the Lipschitz continuity properties established above,
		\begin{equation*}
			\begin{aligned}
				& \| \nabla_V f_p(U_p^{s,0},V^s) - \nabla_V f_p(U_p^{s,k+1},V_p^{s,k}) \|_F^2 \\
                &\leq 2L_{3,p}^2 \|U_p^{s,k+1}-U_p^{s,0}\|_F^2 + 2L_2^2 \|V_p^{s,k}-V^s\|_F^2 .
			\end{aligned}
		\end{equation*}
		Combining the above inequalities gives
		\begin{equation*}
			\begin{aligned}
				(\text{I})-(\text{II})
				&\leq \frac{\tilde\eta L_2^2}{m\tau} \sum_{p=1}^{m} \sum_{k=0}^{\tau-1} \|V_p^{s,k}-V^s\|_F^2  + \frac{\tilde\eta}{m\tau} \sum_{p=1}^{m} \sum_{k=0}^{\tau-1} L_{3,p}^2 \|U_p^{s,k+1}-U_p^{s,0}\|_F^2 .
			\end{aligned}
		\end{equation*}

		Substituting this equation into \eqref{66}, it has 
		\begin{equation}\label{proof_V_descent_start}
			\begin{aligned}
				F(\{ U^{s,0}\},V^{s+1})  &\leq F(\{ U^{s,0}\},{V}^{s})+ 
				(\frac{L_2}{2}-	\frac{1}{2\tilde{\eta}})\|V^{s+1}-V^s\|_F^2\\
                &+\frac{\tilde{\eta}L_2^2}{m\tau}\sum_{p=1}^{m}\sum_{k=0}^{\tau-1}\|V_p^{s,k}-V^s\|_F^2+ (L_2-\frac{1}{2\tilde{\eta}})\|\widetilde V^{s+1}-V^s\|_F^2 \\
				&+\frac{\tilde{\eta}}{m\tau}\sum_{p=1}^{m}\sum_{k=0}^{\tau-1}
				L_{3,p}^2\|U_p^{s,k+1}-U_p^{s,0}\|_F^2 .
			\end{aligned}
		\end{equation}
		By Lemma~\ref{LeA.3}, the change caused by the local $U_p$ updates between two communication rounds is bounded by 
		\begin{equation}\label{proof_use_lemma3}
			\begin{aligned}
				&\quad F(\{U_p^{s+1,0}\},V^{s+1}) - F(\{U_p^{s,0}\},V^{s+1}) \\
				&\leq -\frac{\rho_1}{4mL_{3,a}^2} \sum_{p=1}^{m}\sum_{k=0}^{\tau-1} L_{3,p}^2 	\|\Delta U_p^{s,k}\|_F^2 + \frac{1}{m\rho_1} \sum_{p=1}^{m}\sum_{k=0}^{\tau-1} L_{1,p}^2 \|V_p^{s,k}-V^{s+1}\|_F^2.
			\end{aligned}
		\end{equation}

		The last term in \eqref{proof_use_lemma3} can be controlled as follows. Since $ V_p^{s,k}-V^{s+1} = (V_p^{s,k}-V^s)+(V^s-V^{s+1}),$ it has 
		\begin{equation}\label{proof_cross_error_1} 
			\begin{aligned}
				&\quad\frac{1}{m\rho_1} \sum_{p=1}^{m}\sum_{k=0}^{\tau-1} L_{1,p}^2 \|V_p^{s,k}-V^{s+1}\|_F^2\\
				&\leq \frac{2L_{1,a}^2}{m\rho_1} \sum_{p=1}^{m}\sum_{k=0}^{\tau-1} \|V_p^{s,k}-V^s\|_F^2  + \frac{2\tau L_{1,a}^2}{\rho_1} \|V^{s+1}-V^s\|_F^2 .
			\end{aligned} 
		\end{equation}

		Applying Lemma~\ref{LeA.12} to the first term on the right hand side of \eqref{proof_cross_error_1} gives 
		\begin{equation}\label{proof_cross_error_2} 
			\begin{aligned}
				&\quad\frac{2L_{1,a}^2}{m\rho_1} \sum_{p=1}^{m}\sum_{k=0}^{\tau-1} \|V_p^{s,k}-V^s\|_F^2
				\\
				&\leq \frac{12\tau L_{1,a}^2}{m\rho_1} \|\Lambda^s-\overline{\Lambda}^s\|_F^2 
				+ \frac{12\tau^3\alpha^2L_{1,a}^2}{\rho_1} \| \widetilde{\nabla}h(\widetilde V^{s+1}) + \nabla_V f(\{U_p^{s,0}\},V^s) \|_F^2 \\
				&+ \frac{48\tau^3\alpha^2L_{1,a}^2}{\rho_1} c_h^2 + \frac{24\alpha^2\tau^4L_{1,a}^2}{m\rho_1} \sum_{p=1}^{m}\sum_{k=0}^{\tau-1} L_{3,p}^2 \|\Delta U_p^{s,k}\|_F^2 .
			\end{aligned} 
		\end{equation}

		\textbf{Step 3: It establishes a recursion for the auxiliary function $\Phi^s$.}

		Next, multiplying Lemma~\ref{LeA.21} by $1/\tilde{\eta}$ and using Lemma~\ref{LeA.12}, it obtains
		\begin{equation}\label{proof_Lambda_scaled}
			\begin{aligned}
				\frac{1}{m\tilde{\eta}} \|\Lambda^{s+1}-\overline{\Lambda}^{s+1}\|_F^2 	&\leq \frac{2\alpha^2\tau^2L_2^2}{\tilde{\eta}} \|V^{s+1}-V^s\|_F^2 + \frac{24\alpha^2\tau^2L_2^2}{m\tilde{\eta}}
				\|\Lambda^s-\overline{\Lambda}^s\|_F^2 \\
				&+ \frac{96\alpha^4\tau^4L_2^2}{\tilde{\eta}}c_h^2 + \frac{24\alpha^4\tau^4L_2^2}{\tilde{\eta}}\|
				\widetilde{\nabla}h(\widetilde V^{s+1}) + 	\nabla_V f(\{U_p^{s,0}\},V^s) \|_F^2 \\
				&\quad+ \frac{ 2\alpha^2\tau^2(\tau-1) + 	48\alpha^4\tau^5L_2^2
				}{ m\tilde{\eta} } \sum_{p=1}^{m}\sum_{k=0}^{\tau-1} L_{3,p}^2 \|\Delta U_p^{s,k}\|_F^2 .
			\end{aligned}
		\end{equation}

		Adding \eqref{proof_V_descent_start},	\eqref{proof_use_lemma3}, \eqref{proof_cross_error_1},
		\eqref{proof_cross_error_2}, and \eqref{proof_Lambda_scaled}, and subtracting $F^\star$ from both sides, it gets


















		\begin{equation}\label{proof_before_absorption}
			\begin{aligned}
				\Phi^{s+1}  &\leq \Phi^s -c_1 \| \widetilde{\nabla}h(\widetilde V^{s+1}) + \nabla_V f(\{U_p^{s,0}\},V^s) \|_F^2  - \frac{c_2}{m}\|\Lambda^s-\overline{\Lambda}^s\|_F^2\\
				&  -\frac{c_3}{m}  \sum_{p=1}^{m}\sum_{k=0}^{\tau-1} L_{3,p}^2 \|\Delta U_p^{s,k}\|_F^2  + c_4c_h^2-c_5 \|V^{s+1}-V^s\|_F^2,
			\end{aligned}
		\end{equation}	
		where $c_1$ and $c_4$ are defined in Theorem~\ref{Theorem}, and $c_2=\frac{1}{\tilde\eta} -6\tilde\eta L_2^2 -\frac{24\alpha^2\tau^2L_2^2}{\tilde\eta} -\frac{12\tau L_{1,a}^2}{\rho_1},$ $c_3=\frac{\rho_1}{4L_{3,a}^2}
-\tilde\eta ( \frac{\tau+1}{2}+12L_2^2\alpha^2\tau^3 ) -\frac{2\alpha^2\tau^2(\tau-1) +48\alpha^4\tau^5L_2^2}{\tilde\eta} -\frac{24\alpha^2\tau^4L_{1,a}^2}{\rho_1}$, $c_5= \frac{1-4\alpha^2\tau^2L_2^2}{2\tilde{\eta}} - \frac{L_2}{2} - \frac{2\tau L_{1,a}^2}{\rho_1}.$
The parameter conditions imply
$ \alpha\tau=\frac{\tilde\eta}{\eta_g} \leq\frac{2\tilde\eta}{3},~
L_2\tilde\eta\leq\frac{1}{10},~
\frac{2\tau\tilde\eta L_{1,a}^2}{\rho_1}<\frac{1}{36}.$
Consequently,\begin{equation*}
\begin{aligned}
\tilde\eta c_5
&=\frac12-2\alpha^2\tau^2L_2^2
-\frac{L_2\tilde\eta}{2}
-\frac{2\tau\tilde\eta L_{1,a}^2}{\rho_1}\\
&>\frac12-\frac{2}{225}-\frac{1}{20}-\frac{1}{36}
=\frac{31}{75}>0.
\end{aligned}\end{equation*}	
Thus, $c_5>0$, and omitting the nonpositive term $-c_5\|V^{s+1}-V^s\|_F^2$ yields
		\begin{equation*}
			\begin{aligned}
				\Phi^{s+1}  &\leq \Phi^s -c_1 \| \widetilde{\nabla}h(\widetilde V^{s+1}) + \nabla_V f(\{U_p^{s,0}\},V^s) \|_F^2  - \frac{c_2}{m}\|\Lambda^s-\overline{\Lambda}^s\|_F^2\\
				&  -\frac{c_3}{m}  \sum_{p=1}^{m}\sum_{k=0}^{\tau-1} L_{3,p}^2 \|\Delta U_p^{s,k}\|_F^2  + c_4c_h^2.
			\end{aligned}
		\end{equation*}	
       Following the definition of $C_s,A_s,$ and $R_V^s$ in \eqref{defCsAs} and \eqref{defRVS}, it has
        \begin{equation}\label{masterLyapunovdescent}
		\begin{aligned}
			\Phi^{s+1}-\Phi^s \leq  & -c_1R_V^s -c_2C_s -c_3 A_s +c_4 c_h^2.
		\end{aligned}
	\end{equation}

\textbf{Step 4: It bounds the average stationarity residual $\frac{1}{T}\sum_{s=1}^{T}R_V^s$.}

		Summing the inequality \eqref{masterLyapunovdescent} over $s=1,\cdots,T$ yields
		\begin{equation*}
			\begin{aligned}
				&\Phi^1-\Phi^{T+1} + T c_4c_h^2\geq c_3 A_s +c_1R_V^s + c_2C_s.
			\end{aligned}
		\end{equation*}

		Since $\Phi^{T+1}\geq0$, it has
		\begin{equation*}
			\begin{aligned}
				&\Phi^1 + T c_4c_h^2\geq \sum_{s=1}^{T}(c_1R_V^s + c_2C_s +c_3 A_s) .
			\end{aligned}
		\end{equation*}
		Since $C_s,A_s\geq0$ and $c_1,c_2,c_3>0$, it follows that
