			\begin{aligned}
				&f_p(U_p^{s,k+1},V_p^{s,k}) - f_p(U_p^{s,k},V_p^{s,k})\leq -\frac{\rho_1}{2} \|\Delta U_p^{s,k}\|_F^2.
			\end{aligned}
		\end{equation}
		Next, 
		\begin{equation}\label{U_cross_eval_decomposition}
			\begin{aligned}
				&\quad f_p(U_p^{s,k+1},V^{s+1}) - f_p(U_p^{s,k},V^{s+1}) \\
				&= f_p(U_p^{s,k+1},V_p^{s,k}) - f_p(U_p^{s,k},V_p^{s,k})+( f_p(U_p^{s,k+1},V^{s+1}) \\
				& - f_p(U_p^{s,k+1},V_p^{s,k}))-( f_p(U_p^{s,k},V^{s+1}) - f_p(U_p^{s,k},V_p^{s,k})).
			\end{aligned}
		\end{equation}
		Let $J_p(U) = f_p(U,V^{s+1})-f_p(U,V_p^{s,k}).$ Then the last two bracketed terms of \eqref{U_cross_eval_decomposition} are $J_p(U_p^{s,k+1})-J_p(U_p^{s,k})$. Since the feasible set induced by $U_p\geq 0$ and $U_p^\top U_p=I$ is not convex, the Euclidean line segment between
		$U_p^{s,k}$ and $U_p^{s,k+1}$ may not remain feasible. Hence, it uses the integral form along the Euclidean segment. Since $f_p$ is continuously differentiable in an open neighborhood containing this segment, it has
		\begin{equation*}
			\begin{aligned}
				&J_p(U_p^{s,k+1})-J_p(U_p^{s,k}) = \int_0^1 \langle \nabla_U J_p ( U_p^{s,k} +t(U_p^{s,k+1}-U_p^{s,k}) ), U_p^{s,k+1}-U_p^{s,k} \rangle dt .
			\end{aligned}
		\end{equation*}
		By the Cauchy--Schwarz inequality, it follows that
		\begin{equation*}
			\begin{aligned}
				& |J_p(U_p^{s,k+1})-J_p(U_p^{s,k}) | \leq \sup_{t\in[0,1]} \| \nabla_U J_p ( U_p^{s,k} +t(U_p^{s,k+1}-U_p^{s,k}) ) \|_F  \|U_p^{s,k+1}-U_p^{s,k} \|_F .
			\end{aligned}
		\end{equation*}
		Moreover, since $ \nabla_U J_p(U) = \nabla_U f_p(U,V^{s+1}) - \nabla_U f_p(U,V_p^{s,k}),$ the cross-Lipschitz continuity of $\nabla_U f_p$ with respect to $V$ gives
		\begin{equation*}
			\begin{aligned}
				\|\nabla_U J_p(U) \|_F
				&= \| \nabla_U f_p(U,V^{s+1}) - \nabla_U f_p(U,V_p^{s,k}) \|_F \leq L_{1,p} \|V^{s+1}-V_p^{s,k} \|_F .
			\end{aligned}
		\end{equation*}
		Therefore,
		\begin{equation}\label{U_cross_eval_error}
			\begin{aligned}
				&( f_p(U_p^{s,k+1},V^{s+1}) - f_p(U_p^{s,k+1},V_p^{s,k})) -(  f_p(U_p^{s,k},V^{s+1}) - f_p(U_p^{s,k},V_p^{s,k}))\\
				&\leq L_{1,p} \|V^{s+1}-V_p^{s,k}\|_F \|U_p^{s,k+1}-U_p^{s,k}\|_F.
			\end{aligned}
		\end{equation}
		Applying Young's inequality gives
		\begin{equation}\label{U_cross_eval_young}
			\begin{aligned}
				& L_{1,p} \|V^{s+1}-V_p^{s,k}\|_F \|U_p^{s,k+1}-U_p^{s,k}\|_F \\ &\leq \frac{\rho_1}{4} \|\Delta U_p^{s,k}\|_F^2 + \frac{L_{1,p}^2}{\rho_1} \|V^{s+1}-V_p^{s,k}\|_F^2.
			\end{aligned}
		\end{equation}
		Combining \eqref{U_step_descent_difference}, \eqref{U_cross_eval_decomposition}, \eqref{U_cross_eval_error}, and \eqref{U_cross_eval_young}, we obtain
		\begin{equation}\label{U_single_cross_descent}
			\begin{aligned}
				&f_p(U_p^{s,k+1},V^{s+1}) - f_p(U_p^{s,k},V^{s+1})  \\
                &\leq -\frac{\rho_1}{4} \|\Delta U_p^{s,k}\|_F^2 + \frac{L_{1,p}^2}{\rho_1} \|V^{s+1}-V_p^{s,k}\|_F^2 .
			\end{aligned}
		\end{equation}

		Summing \eqref{U_single_cross_descent} over $k=0,\cdots,\tau-1$ gives
		\begin{equation*}
			\begin{aligned}
				&f_p(U_p^{s,\tau},V^{s+1}) - f_p(U_p^{s,0},V^{s+1})  \\
                &\leq -\frac{\rho_1}{4} \sum_{k=0}^{\tau-1} \|\Delta U_p^{s,k}\|_F^2 + \frac{1}{\rho_1} \sum_{k=0}^{\tau-1} L_{1,p}^2 \|V^{s+1}-V_p^{s,k}\|_F^2 .
			\end{aligned}
		\end{equation*}
		Using $U_p^{s+1,0}=U_p^{s,\tau}$, summing over all clients,
		and multiplying by $1/m$, it has
		\begin{equation}\label{57}
			\begin{aligned}
				&\frac1m\sum_{p=1}^{m}f_p(U_p^{s+1,0},V^{s+1}) - \frac1m\sum_{p=1}^{m}
				f_p(U_p^{s,0},V^{s+1}) \\
				&\leq -\frac{\rho_1}{4m} \sum_{p=1}^{m}\sum_{k=0}^{\tau-1} \|\Delta U_p^{s,k}\|_F^2  + \frac{1}{m\rho_1} \sum_{p=1}^{m}\sum_{k=0}^{\tau-1} L_{1,p}^2 \|V^{s+1}-V_p^{s,k}\|_F^2 .
			\end{aligned}
		\end{equation}
		Since $h(V^{s+1})$ is independent of $\{U_p\}$, the above inequality proves \eqref{roundwise_U_descent_extended}.

		Finally, because $L_{3,p}\leq L_{3,a}$, it has $\|\Delta U_p^{s,k}\|_F^2 \geq \frac{L_{3,p}^2}{L_{3,a}^2} \|\Delta U_p^{s,k}\|_F^2.$
		Substituting this inequality into \eqref{57} yields \eqref{roundwise_U_descent_extended}. This completes the proof.

Under Assumption \ref{assumption2}, it ensures that $U_p^{s,k+1}$ is a global minimizer, and hence a local minimizer, of subproblem~\eqref{Um1}. Since the objective is continuously differentiable and $\mathcal O_p$ is closed, the generalized Fermat rule gives
		\begin{equation*}\label{eq:exact-U-optimality}
			0\in\nabla_{U_p}f_p(U_p^{s,k+1},V_p^{s,k})+\rho_1(U_p^{s,k+1}-U_p^{s,k})+N_{\mathcal O_p}(U_p^{s,k+1}).
		\end{equation*}
		Therefore, there exists $Z_p^{s,k+1}\in N_{\mathcal O_p}(U_p^{s,k+1})$ such that
		\begin{equation*}\label{eq:exact-U-normal}
			\nabla_{U_p}f_p(U_p^{s,k+1},V_p^{s,k})+\rho_1(U_p^{s,k+1}-U_p^{s,k})+Z_p^{s,k+1}=0.
		\end{equation*}
		Using this normal vector in the definition of $r_p^{s,k+1}$, it obtains
		\begin{equation*}
			\begin{aligned}
				r_p^{s,k+1}
				&\leq\|\nabla_{U_p}f_p(U_p^{s,k+1},V^s)+Z_p^{s,k+1}\|_F^2\\
				&=\|\nabla_{U_p}f_p(U_p^{s,k+1},V^s)-\nabla_{U_p}f_p(U_p^{s,k+1},V_p^{s,k})-\rho_1(U_p^{s,k+1}-U_p^{s,k})\|_F^2\\
				&\leq2L_{1,p}^2\|V_p^{s,k}-V^s\|_F^2+2\rho_1^2\|\Delta U_p^{s,k}\|_F^2,
			\end{aligned}
		\end{equation*}
		where the last inequality follows from the cross Lipschitz continuity of $\nabla_{U_p}f_p$ and $\|A+B\|_F^2\leq2\|A\|_F^2+2\|B\|_F^2$. This completes the proof.
